  '@keyframes tornadoSweep{0%{transform:translateX(-20vw) translateY(10vh) scale(0.6) rotate(0deg);opacity:0}10%{opacity:1}90%{opacity:1}100%{transform:translateX(120vw) translateY(-6vh) scale(1.1) rotate(40deg);opacity:0}}',
  '@keyframes tornadoSpin{to{transform:rotate(360deg)}}',
  '@keyframes leafTornado{0%{transform:translate(0,0) rotate(0deg) scale(1);opacity:0.75}30%{transform:translate(8vw,-15vh) rotate(220deg) scale(0.9);opacity:0.8}60%{transform:translate(-6vw,-45vh) rotate(480deg) scale(0.7);opacity:0.7}100%{transform:translate(14vw,-95vh) rotate(900deg) scale(0.35);opacity:0}}',
  // Native (Capacitor) safe-area handling so content clears the phone's
  // status bar (top) and navigation bar (bottom). Harmless in a browser
  // where the insets are 0.
  ':root{--sat:env(safe-area-inset-top,0px);--sab:env(safe-area-inset-bottom,0px);--sal:env(safe-area-inset-left,0px);--sar:env(safe-area-inset-right,0px);}',
  'body{padding-top:var(--sat);padding-bottom:var(--sab);padding-left:var(--sal);padding-right:var(--sar);box-sizing:border-box;}',
