  // -- IndexedDB photo storage -----------------------------------------------
  const openPhotoDB = () => new Promise((resolve, reject) => {
    const req = indexedDB.open('FriendTreePhotos', 2);
    req.onupgradeneeded = e => {
      const db = e.target.result;
      if (!db.objectStoreNames.contains('photos')) db.createObjectStore('photos', { keyPath: 'nodeId' });
      if (!db.objectStoreNames.contains('gallery')) db.createObjectStore('gallery', { keyPath: 'key' });
    };
    req.onsuccess = e => resolve(e.target.result);
    req.onerror = e => reject(e.target.error);
  });


  const saveToGallery = (nodeId, dataUrl, meta) => {
    meta = meta || {};
    return openPhotoDB().then(db => {
      const key = nodeId + '_' + Date.now() + '_' + Math.random().toString(36).slice(2,5);
      return new Promise((res,rej) => {
        const tx = db.transaction('gallery','readwrite');
        tx.objectStore('gallery').put({ key, nodeId, dataUrl, sourceType: meta.sourceType||'manual', date: meta.date||'', taggedNodeIds: meta.taggedNodeIds||[] });
        tx.oncomplete = () => res(key); tx.onerror = rej;
      });
    }).catch(e => console.error('Gallery save failed', e));
  };


  const loadGallery = (nodeId) => {
    return openPhotoDB().then(db => {
      return new Promise((res,rej) => {
        const tx = db.transaction('gallery','readonly');
        const req = tx.objectStore('gallery').getAll();
        req.onsuccess = () => res((req.result||[]).filter(r=>r.nodeId===nodeId));
        req.onerror = rej;
      });
    }).catch(() => []);
  };


  const deleteFromGallery = (key) => {
    return openPhotoDB().then(db => {
      return new Promise((res,rej) => {
        const tx = db.transaction('gallery','readwrite');
        tx.objectStore('gallery').delete(key);
        tx.oncomplete = res; tx.onerror = rej;
      });
    }).catch(e => console.error('Gallery delete failed', e));
  };


  // Update the taggedNodeIds array on a gallery item and persist it
  const updateGalleryItemTags = async (key, taggedNodeIds) => {
    try {
      const db = idbRef.current || (idbRef.current = await openPhotoDB());
      const existing = await new Promise((res, rej) => {
        const tx = db.transaction('gallery', 'readonly');
        const req = tx.objectStore('gallery').get(key);
        req.onsuccess = e => res(e.target.result);
        req.onerror = rej;
      });
      if (!existing) return;
      const updated = { ...existing, taggedNodeIds };
      await new Promise((res, rej) => {
        const tx = db.transaction('gallery', 'readwrite');
        tx.objectStore('gallery').put(updated);
        tx.oncomplete = res; tx.onerror = rej;
      });
      return updated;
    } catch(e) { console.warn('Tag update failed', e); }
  };


  // Resize any source image (data URL) up or down to a standard square,
  // matching the quality standard used for manually-cropped photos elsewhere
  // in the app. Needed specifically because Android's Contacts API returns
  // photos as small thumbnails (often under 200px) -- without this, an
  // imported contact photo would be saved permanently at that tiny
  // resolution, forever, since it otherwise skips the normal crop step
  // entirely.
  const resizeImageDataUrl = (dataUrl, targetSize = 800) => new Promise((resolve) => {
    const img = new Image();
    img.onload = () => {
      const canvas = document.createElement('canvas');
      canvas.width = targetSize; canvas.height = targetSize;
      const ctx = canvas.getContext('2d');
      const iw = img.naturalWidth, ih = img.naturalHeight;
      if (!iw || !ih) { resolve(dataUrl); return; } // couldn't decode -- fall back to original rather than lose it
      // Cover-fit: scale so the shorter side fills the square, centre-cropping
      // the longer side, matching how profile photos are cropped elsewhere.
      const scale = Math.max(targetSize / iw, targetSize / ih);
      const drawW = iw * scale, drawH = ih * scale;
      const dx = (targetSize - drawW) / 2, dy = (targetSize - drawH) / 2;
      ctx.drawImage(img, dx, dy, drawW, drawH);
      resolve(canvas.toDataURL('image/jpeg', 0.9));
    };
    img.onerror = () => resolve(dataUrl); // decode failed -- fall back to original rather than lose it
    img.src = dataUrl;
  });

  const savePhotoToDB = async (nodeId, dataUrl) => {
    const writePromise = (async () => {
      try {
        const db = idbRef.current || (idbRef.current = await openPhotoDB());
        await new Promise((resolve, reject) => {
          const tx = db.transaction('photos', 'readwrite');
          tx.objectStore('photos').put({ nodeId, dataUrl });
          // put() alone doesn't guarantee the write is actually committed --
          // only tx.oncomplete does. Without waiting for this, a write could
          // still be in flight (not yet flushed to disk) at the moment the
          // app closes, even though the call itself had already "returned".
          tx.oncomplete = () => resolve();
          tx.onerror = () => reject(tx.error);
        });
        // ALSO write to genuine device file storage, not just IndexedDB --
        // IndexedDB lives inside the app's own sandboxed storage, which can
        // still be cleared by the OS, an app data reset, or an uninstall.
        // Writing a real file to the DOCUMENTS directory (the same location
        // and naming convention the existing backup-restore code already
        // uses) makes the photo durable independent of the app's own data,
        // and consistent with how a restore already expects to find it.
        try {
          const isNative = !!(window.Capacitor && window.Capacitor.isNativePlatform && window.Capacitor.isNativePlatform());
          const FilesystemP = window.Capacitor && window.Capacitor.Plugins && window.Capacitor.Plugins.Filesystem;
          if (isNative && FilesystemP && dataUrl && dataUrl.startsWith('data:image')) {
            const b64 = dataUrl.split(',')[1];
            const ext = dataUrl.startsWith('data:image/png') ? 'png' : 'jpg';
            await FilesystemP.writeFile({ path: `ft_photo_${nodeId}.${ext}`, data: b64, directory: 'DOCUMENTS', recursive: true });
          }
        } catch(fsErr) { console.warn('Filesystem photo write failed:', fsErr); }
      } catch(e) { console.warn('Photo save failed:', e); }
    })();
    pendingPhotoWrites.current.add(writePromise);
    writePromise.finally(() => pendingPhotoWrites.current.delete(writePromise));
    return writePromise;
  };


  const deletePhotoFromDB = async (nodeId) => {
    try {
      const db = idbRef.current || (idbRef.current = await openPhotoDB());
      const tx = db.transaction('photos', 'readwrite');
      tx.objectStore('photos').delete(nodeId);
    } catch(e) {}
  };

  // Save every photo in a person's carousel array durably, not just the
  // single current one -- uses a composite key per index so all of them
  // survive an app restart, fixing the gap where only the first photo per
  // person was ever backed up.
  const savePhotoArrayToDB = async (nodeId, photosArray) => {
    if (!Array.isArray(photosArray) || photosArray.length === 0) return;
    const writes = photosArray.map((p, i) => {
      const dataUrl = p?.cropped || p?.orig;
      if (!dataUrl) return Promise.resolve();
      return savePhotoToDB(`${nodeId}_photo_${i}`, dataUrl);
    });
    await Promise.all(writes);
    // Also record how many entries exist, so restore knows where to stop
    // looking without needing to probe indefinitely
    try {
      const Prefs = window.Capacitor?.Plugins?.Preferences;
      if (Prefs && typeof Prefs.set === 'function') {
        await Prefs.set({ key: `ft_photo_count_${nodeId}`, value: String(photosArray.length) });
      }
    } catch(e) {}
  };


  // On mount — ask the OS to PERSIST our storage so Android doesn't evict
  // IndexedDB (which is why photos vanished after closing the native app).
  useEffect(() => {
    (async () => {
      try {
        if (navigator.storage && navigator.storage.persist) {
          const already = navigator.storage.persisted ? await navigator.storage.persisted() : false;
          if (already) {
            console.log('Persistent storage: already granted');
            showToast('✅ Persistent storage already granted');
          } else {
            const granted = await navigator.storage.persist();
            console.log('Persistent storage:', granted ? 'granted' : 'denied');
            // Surface this directly -- if denied, Android can clear app
            // storage (including localStorage, not just IndexedDB) under
            // normal storage pressure, which would explain data loss that
            // has nothing to do with the app-closing timing at all.
            if (!granted) {
              showToast('⚠️ Persistent storage denied by Android — data may be at risk of being cleared');
            }
          }
        } else {
          showToast('⚠️ Persistent storage API not available on this device');
        }
      } catch(e) {
        console.warn('storage.persist failed:', e);
        showToast('⚠️ Storage persistence check failed: ' + e.message);
      }
    })();
  }, []);


  // When the user shares an Instagram/Messenger/etc. profile into FriendshipTree,
  // capture it and ask which friend it's for.
  const [sharedLink, setSharedLink] = useState(null); // the incoming url string
  useEffect(() => {
    const SI = window.Capacitor && window.Capacitor.Plugins && window.Capacitor.Plugins.SendIntent;
    if (!SI) return;
    let listener;
    const handle = (data) => {
      // data.url holds the shared text/link (plugin returns it url-encoded)
      let url = data && (data.url || data.text);
      if (!url) return;
      try { url = decodeURIComponent(url); } catch(_) {}
      // pull the first http(s) link out of the shared text if there's extra wording
      const m = url.match(/https?:\/\/[^\s]+/);
      setSharedLink(m ? m[0] : url);
    };
    // check for an intent that launched the app
    try { if (SI.checkSendIntentReceived) SI.checkSendIntentReceived().then(d => { if (d) handle(d); }).catch(()=>{}); } catch(_){}
    // and listen for intents while running
    try { listener = SI.addListener && SI.addListener('appSendActionIntent', handle); } catch(_){}
    return () => { try { listener && listener.remove && listener.remove(); } catch(_){} };
  }, []);




  // On mount — restore photos from IndexedDB onto nodes
  useEffect(() => {
    (async () => {
      setPhotosRestoring(true);
      try {
        const db = await openPhotoDB();
        idbRef.current = db;
        const tx = db.transaction('photos', 'readonly');
        const all = await new Promise((res, rej) => {
          const req = tx.objectStore('photos').getAll();
          req.onsuccess = () => res(req.result);
          req.onerror = () => rej(req.error);
        });
        if (all.length === 0) {
          // IndexedDB is completely empty -- this is exactly the scenario the
          // Filesystem backup exists to protect against (e.g. the app's own
          // storage was cleared, but real files on the device survived).
          // Attempt to recover from those durable copies before giving up.
          try {
            const isNative = !!(window.Capacitor && window.Capacitor.isNativePlatform && window.Capacitor.isNativePlatform());
            const FilesystemP = window.Capacitor && window.Capacitor.Plugins && window.Capacitor.Plugins.Filesystem;
            if (isNative && FilesystemP) {
              const listing = await FilesystemP.readdir({ path: '', directory: 'DOCUMENTS' }).catch(() => null);
              const photoFiles = (listing && listing.files || []).filter(f => {
                const name = typeof f === 'string' ? f : f.name;
                return name && name.startsWith('ft_photo_');
              });
              if (photoFiles.length > 0) {
                showToast(`🔄 Recovering ${photoFiles.length} photo(s) from device storage…`);
                for (const f of photoFiles) {
                  const name = typeof f === 'string' ? f : f.name;
                  const match = name.match(/^ft_photo_(.+)\.(jpg|png)$/);
                  if (!match) continue;
                  const nodeId = match[1];
                  const ext = match[2];
                  try {
                    const readResult = await FilesystemP.readFile({ path: name, directory: 'DOCUMENTS' });
                    const dataUrl = `data:image/${ext === 'png' ? 'png' : 'jpeg'};base64,${readResult.data}`;
                    await savePhotoToDB(nodeId, dataUrl);
                  } catch (readErr) { console.warn('Recovery read failed for', name, readErr); }
                }
                // Re-fetch now that IndexedDB has been repopulated, so the
                // normal restore flow below picks up the recovered photos.
                const tx2 = db.transaction('photos', 'readonly');
                const recovered = await new Promise((res, rej) => {
                  const req = tx2.objectStore('photos').getAll();
                  req.onsuccess = () => res(req.result);
                  req.onerror = () => rej(req.error);
                });
                if (recovered.length > 0) { all.push(...recovered); }
              }
            }
          } catch (recoveryErr) { console.warn('Photo recovery attempt failed:', recoveryErr); }
          if (all.length === 0) { setPhotosRestoring(false); return; }
        }
        // Apply photos in small SEQUENTIAL batches rather than one giant
        // simultaneous update -- this is what makes photos appear
        // progressively as they load, instead of everyone waiting through a
        // silent delay and then seeing every photo pop in at once.
        const BATCH_SIZE = 4;
        for (let i = 0; i < all.length; i += BATCH_SIZE) {
          const batch = all.slice(i, i + BATCH_SIZE);
          const photoMap = {};
          batch.forEach(({ nodeId, dataUrl }) => { if (dataUrl) photoMap[nodeId] = dataUrl; });
          setNodes(prev => prev.map(n => {
            if (!photoMap[n.id]) return n;
            // Restoring the main icon photo without also putting it back into the
            // `photos` carousel array is exactly why the profile-pictures row at
            // the top of a person's window stayed blank after every restart -- the
            // icon worked because it reads `img` directly, but that row reads only
            // from `photos`, which this restore never touched.
            const restored = photoMap[n.id];
            const already = (n.photos || []).some(p => p.cropped === restored);
            const photos = already ? n.photos : [...(n.photos || []), { orig: restored, cropped: restored }];
            return { ...n, img: restored, photos, activePhotoIdx: already ? n.activePhotoIdx : photos.length - 1 };
          }));
          // Small pause between batches so the update genuinely renders as a
          // visible step rather than all batches collapsing into one paint.
          if (i + BATCH_SIZE < all.length) await new Promise(r => setTimeout(r, 60));
        }
        // Second pass: reconstruct full multi-photo carousels from the
        // composite-keyed entries (${nodeId}_photo_${i}) written by
        // savePhotoArrayToDB -- these are already in `all` since they share
        // the same IndexedDB store, we just need to group and order them.
        const arrayEntryPattern = /^(.+)_photo_(\d+)$/;
        const byNode = {};
        all.forEach(({ nodeId, dataUrl }) => {
          const m = nodeId.match(arrayEntryPattern);
          if (m && dataUrl) {
            const [, realNodeId, idxStr] = m;
            (byNode[realNodeId] = byNode[realNodeId] || [])[parseInt(idxStr, 10)] = dataUrl;
          }
        });
        const nodesWithArrays = Object.keys(byNode);
        if (nodesWithArrays.length > 0) {
          setNodes(prev => prev.map(n => {
            const entries = byNode[n.id];
            if (!entries) return n;
            const photos = entries.filter(Boolean).map(dataUrl => ({ orig: dataUrl, cropped: dataUrl }));
            if (photos.length === 0) return n;
            return { ...n, photos, activePhotoIdx: photos.length - 1, img: photos[photos.length-1].cropped };
          }));
        }
      } catch(e) { console.warn('Photo restore failed:', e); }
      setPhotosRestoring(false);
    })();
  }, []); // eslint-disable-line


  // Auto-create hidden hubs for any person who has at least one real CHILD
  // of their own -- someone reachable by moving away from social, not merely
  // anyone connected to them at all. This directional check is essential:
  // treating "has someone attached" symmetrically would also match a pure
  // leaf (someone who only has a PARENT attached, no children), which then
  // fights the cleanup effect below in an infinite loop -- cleanup retires
  // their hub for being a now-demoted descendant, creation immediately
  // recreates it because they're still "connected to someone", forever.
  useEffect(() => {
    const isRealPerson = (n) => n && n.type !== 'hub' && n.type !== 'flower' && n.id !== 'me';
    const isHiddenHubId = (id) => { const n = nodes.find(x => x.id === id); return !!(n && n.type === 'hub' && n.hidden); };
    // Real adjacency only -- hidden-hub edges are pure bookkeeping, never
    // genuine tree structure, so they're excluded from the direction test.
    const realAdj = {};
    links.forEach(l => {
      if (isHiddenHubId(l.source) || isHiddenHubId(l.target)) return;
      (realAdj[l.source] = realAdj[l.source] || []).push(l.target);
      (realAdj[l.target] = realAdj[l.target] || []).push(l.source);
    });
    // Parent-toward-social pointer for every real node, via BFS from social --
    // whoever discovered a node IS that node's real parent, so anyone who
    // appears as someone else's discovered neighbour (i.e. is some OTHER
    // node's parent value) has at least one real child.
    const parent = { flower_social: null };
    let frontier = ['flower_social'];
    let guard = 0;
    while (frontier.length > 0 && guard < 5000) {
      const next = [];
      frontier.forEach(id => {
        guard++;
        (realAdj[id] || []).slice().sort().forEach(oid => {
          if (oid in parent) return;
          parent[oid] = id;
          next.push(oid);
        });
      });
      next.sort();
      frontier = next;
    }
    const realParents = new Set(Object.values(parent).filter(Boolean));
    const onSocialDirectly = new Set(
      links
        .filter(l => l.source === 'flower_social' || l.target === 'flower_social')
        .map(l => l.source === 'flower_social' ? l.target : l.source)
    );

    const newHubs = [];
    const newHubLinks = [];
    nodes
      .filter(isRealPerson)
      // Anyone directly on social always gets their own group ready to use,
      // even before they've added anyone -- matching the original behaviour.
      // Anyone deeper in the tree only gets one once they actually have a
      // real child of their own.
      .filter(person => onSocialDirectly.has(person.id) || realParents.has(person.id))
      .forEach(person => {
        const id = person.id;
        const hubId = 'hidden_hub_' + id;
        if (!nodes.some(n => n.id === hubId)) {
          newHubs.push({ id: hubId, type: 'hub', hidden: true, label: (person && person.label ? person.label : 'Friend') + "'s Group", x: (person && person.x ? person.x : 0) + 180, y: (person && person.y ? person.y : 0), pinned: false });
        }
        if (!links.some(l => (l.source===hubId&&l.target===id)||(l.target===hubId&&l.source===id))) {
          newHubLinks.push({ source: hubId, target: id });
        }
      });
    if (newHubs.length > 0) setNodes(prev => [...prev, ...newHubs]);
    if (newHubLinks.length > 0) setLinks(prev => [...prev, ...newHubLinks]);


    // Repair any hidden hub whose label is missing/undefined — name it after
    // the person it belongs to (e.g. "Hayley's Group").
    setNodes(prev => {
      let changed = false;
      const fixed = prev.map(n => {
        if (n.type === 'hub' && n.hidden && (!n.label || n.label === 'undefined' || /^undefined/.test(n.label))) {
          const personId = n.id.replace('hidden_hub_', '');
          const person = prev.find(p => p.id === personId);
          if (person && person.label) { changed = true; return { ...n, label: person.label + "'s Group" }; }
        }
        return n;
      });
      return changed ? fixed : prev;
    });
  }, [links]); // eslint-disable-line


  // Actively retire a hidden hub the moment its anchor person becomes someone
  // ELSE's descendant via real structure -- i.e. another hidden hub's anchor
  // (or visible hub) now sits between them and social. This is what makes a
  // person's grouping reflect their CURRENT connections only: the instant
  // Josh is linked through Sam (who's linked through Dad, Family, Social),
  // Josh's own old hidden hub (left over from once being on social directly)
  // gets deleted outright, rather than competing for him indefinitely.
  //
  // The key insight: "is this person reachable from social" is true for
  // EVERYONE in a connected tree, so that alone can't distinguish a genuine
  // root from a now-demoted leftover. What actually matters is whether
  // ANOTHER hidden hub's own anchor sits on the real path between this
  // anchor and social -- if so, this anchor is that other anchor's
  // descendant now, not a root in their own right.
  useEffect(() => {
    const hiddenHubs = nodes.filter(n => n.type === 'hub' && n.hidden);
    if (hiddenHubs.length === 0) return;
    const isHiddenHubId = (id) => { const n = nodes.find(x => x.id === id); return !!(n && n.type === 'hub' && n.hidden); };
    // Real adjacency only -- every hidden-hub edge is excluded entirely, since
    // it's pure bookkeeping, never genuine tree structure.
    const realAdj = {};
    links.forEach(l => {
      if (isHiddenHubId(l.source) || isHiddenHubId(l.target)) return;
      (realAdj[l.source] = realAdj[l.source] || []).push(l.target);
      (realAdj[l.target] = realAdj[l.target] || []).push(l.source);
    });
    // Parent-toward-social pointer for every real node, via BFS from social.
    const parent = { flower_social: null };
    let frontier = ['flower_social'];
    let guard = 0;
    while (frontier.length > 0 && guard < 5000) {
      const next = [];
      frontier.forEach(id => {
        guard++;
        (realAdj[id] || []).slice().sort().forEach(oid => {
          if (oid in parent) return;
          parent[oid] = id;
          next.push(oid);
        });
      });
      next.sort();
      frontier = next;
    }
    const onSocialDirectly = new Set(
      links
        .filter(l => l.source === 'flower_social' || l.target === 'flower_social')
        .map(l => l.source === 'flower_social' ? l.target : l.source)
    );
    const realParents = new Set(Object.values(parent).filter(Boolean));
    const toRetire = [];
    hiddenHubs.forEach(hub => {
      const anchorId = hub.id.replace('hidden_hub_', '');
      if (!nodes.some(n => n.id === anchorId)) { toRetire.push(hub.id); return; } // anchor itself is gone
      if (!(anchorId in parent)) return; // not reachable from social at all yet -- leave alone
      // Use the EXACT SAME eligibility test the creation effect uses, just
      // inverted: a hub survives only if its anchor still qualifies for one
      // right now (directly on social, or a genuine parent of their own).
      // Anyone who no longer meets either condition -- like Ella, who has no
      // children and reaches social only via Imogen now -- gets retired,
      // regardless of whether the person now "above" them happens to have
      // their own hidden hub or not. Using the identical condition in both
      // effects is what guarantees they can never disagree with each other.
      const stillEligible = onSocialDirectly.has(anchorId) || realParents.has(anchorId);
      if (!stillEligible) toRetire.push(hub.id);
    });

    if (toRetire.length > 0) {
      const retireSet = new Set(toRetire);
      setNodes(prev => prev.filter(n => !retireSet.has(n.id)));
      setLinks(prev => prev.filter(l => !retireSet.has(l.source) && !retireSet.has(l.target)));
    }
  }, [links]); // eslint-disable-line


